def strip_line_comments(sql):
    out, in_str, i = [], False, 0
    while i < len(sql):
        c = sql[i]
        if c == "'":
            in_str = not in_str
        if not in_str and sql.startswith("--", i):
            j = sql.find("\n", i)
            i = len(sql) if j < 0 else j
            continue
        out.append(c)
        i += 1
    return "".join(out)

