def chunked(iterable, size):
    if size < 1:
        raise ValueError("size must be at least 1")
    out, part = [], []
    for x in iterable:
        part.append(x)
        if len(part) == size:
            out.append(part)
            part = []
    if part:
        out.append(part)
    return out
